      <v-list class="white--text">
        <v-list-item>
          <v-btn class="primary" dark @click="goBack">
            <v-icon light left>mdi-arrow-left</v-icon>
            <span>Go Back</span>
          </v-btn>
        </v-list-item>
      </v-list>
    </v-navigation-drawer>

    <!-- ═══════════════════════════════════════════ HERO ══ -->
    <div class="rrr-hero">
      <div class="rrr-hero__left">
        <div class="rrr-hero__icon">
          <v-icon color="white" size="22">mdi-clipboard-check-outline</v-icon>
        </div>
        <div>
          <div class="rrr-hero__title">
            Review Training Recommendation Response
          </div>
          <div class="rrr-hero__sub">
            Review the HOD response and approve or reject participant
            nominations
          </div>
        </div>
      </div>
      <div
        class="rrr-hero__stat"
        v-if="!loading && responseData && staffInCoverage"
      >
        <div class="rrr-hero__stat-val">{{ participants.length }}</div>
        <div class="rrr-hero__stat-lbl">Nominees</div>
      </div>
    </div>

    <!-- Loading / access check state -->
    <v-row v-if="!accessChecked || loading" class="mt-4">
      <v-col cols="12" class="text-center">
        <v-progress-circular
          indeterminate
          color="primary"
          size="64"
        ></v-progress-circular>
        <p class="mt-3 text-h6">
          {{ !accessChecked ? 'Verifying access…' : 'Loading training recommendation...' }}
        </p>
      </v-col>
    </v-row>

    <!-- Access denied -->
    <v-container v-else-if="!isHR" class="mt-4">
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Access Restricted</div>
            <div>
              This module is only accessible to District HR personnel. Your
              account does not have the required HR role.
            </div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-lock-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <!-- Access denied: participants outside HR's facility coverage -->
    <v-container
      v-else-if="!loading && !staffInCoverage"
      class="mt-4"
    >
      <v-alert type="error" outlined prominent border="left">
        <v-row align="center">
          <v-col class="grow">
            <div class="font-weight-bold text-h6 mb-1">Access Restricted</div>
            <div>
              One or more participants in this response are outside your HR
              coverage area.
            </div>
          </v-col>
          <v-col class="shrink">
            <v-icon size="48" color="error">mdi-lock-outline</v-icon>
          </v-col>
        </v-row>
      </v-alert>
    </v-container>

    <!-- Error State -->
    <v-alert
      v-if="accessChecked && isHR && staffInCoverage && error"
      type="error"
      dismissible
      @input="error = false"
      class="mt-4"
    >
      {{ errorMessage }}
    </v-alert>

    <!-- Main Content -->
    <v-row
      v-if="accessChecked && isHR && staffInCoverage && !loading && responseData"
      class="mt-4"
    >
      <!-- Left Column - Response Details -->
      <v-col cols="12" lg="7">
        <!-- HOD Response Card -->
        <v-card outlined class="elevation-2 mb-4">
          <v-card-title class="indigo darken-1 white--text py-3">
            <v-icon left color="white">mdi-file-document-outline</v-icon>
            HOD Training Recommendation Response
          </v-card-title>
          <v-card-text class="pa-4">
            <!-- Department -->
            <v-row dense class="mb-3">
              <v-col cols="12">
                <div
                  class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                >
                  RESPONDED DEPARTMENT
                </div>
                <v-chip color="blue" text-color="white" small>
                  {{ responseData.department }}
                </v-chip>
              </v-col>
            </v-row>

            <v-divider class="my-3"></v-divider>

            <!-- HOD Response -->
            <v-row dense>
              <v-col cols="12" md="6">
                <div
                  class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                >
                  HOD RESPONSE
                </div>
                <v-chip
                  :color="getResponseColor(responseData.response)"
                  text-color="white"
                  small
                >
                  <v-icon small left>{{
                    getResponseIcon(responseData.response)
                  }}</v-icon>
                  {{ responseData.responseDisplay }}
                </v-chip>
              </v-col>
              <v-col cols="12" md="6">
                <div
                  class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                >
                  SUBMISSION DATE
                </div>
                <div class="body-2">
                  <v-icon small color="grey">mdi-calendar</v-icon>
                  {{ formatDate(responseData.submissionDate) }}
                </div>
              </v-col>
            </v-row>

            <!-- HOD Comments -->
            <v-row dense class="mb-3" v-if="responseData.hodComments">
              <v-col cols="12">
                <div
                  class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                >
                  HOD COMMENTS
                </div>
                <v-card outlined class="pa-3 blue-grey lighten-5">
                  <div class="body-2">{{ responseData.hodComments }}</div>
                </v-card>
              </v-col>
            </v-row>

            <v-divider class="my-3"></v-divider>

            <!-- Nominated Participants -->
            <v-row dense>
              <v-col cols="12">
                <div
                  class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                >
                  NOMINATED PARTICIPANTS ({{ participants.length }})
                </div>

                <v-card
                  v-if="participants.length === 0"
                  outlined
                  class="pa-3 text-center"
                >
                  <v-icon color="grey" size="48">mdi-account-off</v-icon>
                  <p class="grey--text mt-2">No participants nominated</p>
                </v-card>

                <v-list v-else dense class="pa-0">
                  <v-list-item
                    v-for="(participant, index) in participants"
                    :key="index"
                    class="mb-2 elevation-1 rounded"
                  >
                    <v-list-item-avatar color="primary">
                      <v-icon dark>mdi-account</v-icon>
                    </v-list-item-avatar>
                    <v-list-item-content>
                      <v-list-item-title class="font-weight-medium">
                        {{ participant.name }}
                      </v-list-item-title>
                      <v-list-item-subtitle>
                        {{ participant.jobTitle }} - {{ participant.grade }} -
                        {{ participant.age }} Years
                      </v-list-item-subtitle>
                    </v-list-item-content>
                  </v-list-item>
                </v-list>
              </v-col>
            </v-row>
            <!-- Training Recommendation Details -->
            <v-row class="mt-4">
              <v-col cols="12">
                <v-card outlined class="elevation-3">
                  <v-card-title class="primary white--text py-4">
                    <v-icon left color="white" large>mdi-school-outline</v-icon>
                    <div>
                      <div class="text-h5">
                        {{ trainingRecommendation.title }}
                      </div>
                      <div class="caption mt-1">
                        Training Recommendation Details
                      </div>
                    </div>
                  </v-card-title>

                  <v-card-text class="pa-6">
                    <!-- Recommendation Details Grid -->
                    <v-row dense>
                      <v-col cols="12" md="12">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          TRAINING DESCRIPTION
                        </div>
                        <p class="body-1 font-weight-medium text--darken-3">
                          {{
                            trainingRecommendation.description ||
                              "No description provided"
                          }}
                        </p>
                      </v-col>
                      <v-col cols="6">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          TRAINING INSTITUTION
                        </div>
                        <div class="body-2 font-weight-medium">
                          {{ trainingRecommendation.institution }}
                        </div>
                        <template v-if="trainingRecommendation.qualification">
                          <div
                            class="caption grey--text text--darken-2 mb-1 font-weight-bold mt-3"
                          >
                            QUALIFICATION
                          </div>
                          <div class="body-2 font-weight-medium">
                            <v-icon small color="grey darken-2">mdi-school-outline</v-icon>
                            {{ trainingRecommendation.qualification }}
                          </div>
                          <v-chip
                            v-if="trainingRecommendation.qualificationLevel"
                            x-small
                            color="purple lighten-5"
                            text-color="purple darken-3"
                            class="mt-1"
                          >
                            {{ trainingRecommendation.qualificationLevel }}
                          </v-chip>
                        </template>
                        <template v-if="trainingRecommendation.country">
                          <div
                            class="caption grey--text text--darken-2 mb-1 font-weight-bold mt-3"
                          >
                            COUNTRY
                          </div>
                          <div class="body-2 font-weight-medium">
                            <v-icon small color="grey darken-2">mdi-flag-outline</v-icon>
                            {{ trainingRecommendation.country }}
                          </div>
                        </template>
                      </v-col>
                      <v-col cols="6">
                        <v-row dense>
                          <v-col cols="12">
                            <div
                              class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                            >
                              DEPARTMENT
                            </div>
                            <v-chip
                              color="blue lighten-5"
                              text-color="blue darken-4"
                              small
                              :key="dep.name + dep.participants"
                              v-for="dep in trainingRecommendation.departments"
                            >
                              <span class="font-weight-medium"
                                >{{ dep.name }} - ({{
                                  dep.participants
                                }}
                                Participants)</span
                              >
                            </v-chip>
                          </v-col>
                        </v-row>
                      </v-col>
                    </v-row>

                    <v-divider class="my-4"></v-divider>

                    <v-row dense>
                      <v-col cols="12" sm="6" md="4">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          START DATE
                        </div>
                        <div class="body-2 font-weight-medium">
                          <v-icon small color="grey darken-2"
                            >mdi-calendar-start</v-icon
                          >
                          {{ formatDate(trainingRecommendation.startDate) }}
                        </div>
                      </v-col>
                      <v-col cols="12" sm="6" md="4">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          END DATE
                        </div>
                        <div class="body-2 font-weight-medium">
                          <v-icon small color="grey darken-2"
                            >mdi-calendar-end</v-icon
                          >
                          {{ formatDate(trainingRecommendation.endDate) }}
                        </div>
                      </v-col>
                      <v-col cols="12" sm="6" md="4">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          MAX PARTICIPANTS
                        </div>
                        <div class="body-2 font-weight-medium">
                          <v-icon small color="grey darken-2"
                            >mdi-account-group</v-icon
                          >
                          {{
                            trainingRecommendation.maxParticipants ||
                              "Not specified"
                          }}
                        </div>
                      </v-col>
                    </v-row>
                    <v-divider></v-divider>
                    <v-row
                      dense
                      class="mt-2"
                      v-if="trainingRecommendation.methodology"
                    >
                      <v-col cols="12" sm="6">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          LEARNING METHODOLOGY
                        </div>
                        <v-chip small outlined color="primary">
                          <span class="font-weight-medium">{{
                            trainingRecommendation.methodology
                          }}</span>
                        </v-chip>
                      </v-col>
                      <v-col cols="12" sm="6" md="6">
                        <div
                          class="caption grey--text text--darken-2 mb-1 font-weight-bold"
                        >
                          LOCATION
                        </div>
                        <div class="body-2 font-weight-medium">
                          <v-icon small color="grey darken-2"
                            >mdi-map-marker</v-icon
                          >
                          {{
                            trainingRecommendation.location || "Not specified"
                          }}
                        </div>
                      </v-col>
                    </v-row>

                    <!-- NEW: Eligibility Criteria Section -->
                    <v-divider class="my-4"></v-divider>
                    <div class="text-h6 font-weight-bold mb-3 primary--text">
                      <v-icon color="primary" class="mr-2"
                        >mdi-account-check</v-icon
                      >
                      Eligibility Criteria
                    </div>

                    <v-row dense>
                      <!-- Designations -->
                      <v-col
                        cols="12"
                        sm="6"
                        md="4"
                        v-if="
                          trainingRecommendation.designations &&
                            trainingRecommendation.designations.length > 0
                        "
                      >
                        <div
                          class="caption grey--text text--darken-2 mb-2 font-weight-bold"
                        >
                          TARGET DESIGNATIONS
                        </div>
                        <v-chip
                          v-for="(designation,
                          index) in trainingRecommendation.designations"
                          :key="'designation-' + index"
                          color="blue lighten-5"
                          text-color="blue darken-4"
                          small
                          class="mr-1 mb-1"
                        >
                          <v-icon small left>mdi-briefcase</v-icon>
                          <span class="font-weight-medium">{{
                            designation
                          }}</span>
                        </v-chip>
                      </v-col>

                      <!-- Salary Grades -->
                      <v-col
                        cols="12"
                        sm="6"
                        md="4"
                        v-if="
                          trainingRecommendation.salaryGrades &&
                            trainingRecommendation.salaryGrades.length > 0
                        "
                      >
                        <div
                          class="caption grey--text text--darken-2 mb-2 font-weight-bold"
                        >
                          TARGET SALARY GRADES
                        </div>
                        <v-chip
                          v-for="(grade,
                          index) in trainingRecommendation.salaryGrades"
                          :key="'grade-' + index"
                          color="green lighten-5"
                          text-color="green darken-4"
                          small
                          class="mr-1 mb-1"
                        >
                          <v-icon small left>mdi-cash</v-icon>
                          <span class="font-weight-medium">{{ grade }}</span>
                        </v-chip>
                      </v-col>

                      <!-- Age Criteria -->
                      <v-col
                        cols="12"
                        sm="6"
                        md="4"
                        v-if="
                          trainingRecommendation.ageCriteria &&
                            trainingRecommendation.ageCriteria.length > 0
                        "
                      >
                        <div
                          class="caption grey--text text--darken-2 mb-2 font-weight-bold"
                        >
                          AGE REQUIREMENTS
                        </div>
                        <v-chip
                          v-for="(ageCriterion,
                          index) in trainingRecommendation.ageCriteria"
                          :key="'age-' + index"
                          color="orange lighten-5"
                          text-color="orange darken-4"
                          small
                          class="mr-1 mb-1"
                        >
                          <v-icon small left>mdi-calendar-account</v-icon>
                          <span class="font-weight-medium">{{
                            formatAgeCriteria(ageCriterion)
                          }}</span>
                        </v-chip>
                      </v-col>
                    </v-row>
                  </v-card-text>
                </v-card>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>

        <!-- Existing HR Review (if exists and read-only) -->
        <v-card
          v-if="existingReview && isReadOnly"
          outlined
          class="elevation-2 mb-4"
        >
          <v-card-title class="primary darken-2 white--text py-3">
            <v-icon left color="white">mdi-eye</v-icon>
            Existing HR Review (Read Only)
          </v-card-title>
          <v-card-text class="pa-4">
            <v-row dense class="mb-3">
              <v-col cols="12" md="6">
                <div class="caption grey--text mb-1">DECISION</div>
                <v-chip
                  :color="
                    existingReview.decision === 'approved' ? 'green' : 'red'
                  "
                  text-color="white"
                  small
                >
                  {{
                    existingReview.decision === "approved"
                      ? "APPROVED"
                      : "REJECTED"
                  }}
                </v-chip>
              </v-col>
              <v-col cols="12" md="6">
                <div class="caption grey--text mb-1">REVIEW DATE</div>
                <div class="body-2">
                  <v-icon small color="grey">mdi-calendar</v-icon>
                  {{ formatDate(existingReview.reviewDate) }}
                </div>
              </v-col>
            </v-row>

            <v-row dense class="mb-3">
              <v-col cols="12">
                <div class="caption grey--text mb-1">REVIEWER</div>
                <div class="body-2">{{ existingReview.reviewerName }}</div>
              </v-col>
            </v-row>

            <v-row dense>
              <v-col cols="12">
                <div class="caption grey--text mb-1">COMMENTS</div>
                <v-card outlined class="pa-3 blue-grey lighten-5">
                  <div class="body-2">{{ existingReview.comments }}</div>
                </v-card>
              </v-col>
            </v-row>

            <v-alert
              v-if="responseData.status === 'approved'"
              type="info"
              outlined
              dense
              class="mt-3"
            >
              <v-icon small>mdi-lock</v-icon>
              This review is locked because the response has been approved.
            </v-alert>

            <v-alert
              v-if="responseData.status === 'rejected' && !canEdit"
              type="warning"
              outlined
              dense
              class="mt-3"
            >
              <v-icon small>mdi-lock-clock</v-icon>
              This review is locked because more than 10 days have passed since
              rejection ({{ daysSinceReview }} days ago).
            </v-alert>
          </v-card-text>
        </v-card>
      </v-col>

      <!-- Right Column - HR Review Form -->
      <v-col cols="12" lg="5">
        <v-card outlined class="elevation-2 sticky-card">
          <v-card-title
            :class="
              isReadOnly
                ? 'grey darken-2 white--text py-3'
                : 'green darken-1 white--text py-3'
            "
          >
            <v-icon left color="white">
              {{ isReadOnly ? "mdi-eye" : "mdi-clipboard-check" }}
            </v-icon>
            {{
              isReadOnly
                ? "HR Review (Read Only)"
                : existingReview
                ? "Edit HR Review"
                : "HR Review & Decision"
            }}
          </v-card-title>
          <v-card-text class="pa-4">
            <!-- Read-Only Message -->
            <v-alert v-if="isReadOnly" type="info" outlined class="mb-4">
              <div class="font-weight-medium">Review Cannot Be Modified</div>
              <div class="mt-1 text-caption">
                {{ readOnlyReason }}
              </div>
            </v-alert>

            <!-- Edit Warning -->
            <v-alert
              v-if="!isReadOnly && existingReview"
              type="warning"
              outlined
              class="mb-4"
            >
              <div class="font-weight-medium">Editing Existing Review</div>
              <div class="mt-1 text-caption">
                You are editing a review that was submitted
                {{ daysSinceReview }} days ago. Changes will update the existing
                review.
              </div>
            </v-alert>

            <v-form ref="form" v-model="valid">
              <!-- Current Status Display -->
              <v-alert
                border="left"
                colored-border
                type="info"
                elevation="2"
                class="mb-4"
              >
                <div class="font-weight-medium">Current Status</div>
                <div class="mt-1">{{ responseData.statusDisplay }}</div>
              </v-alert>

              <!-- Review Decision -->
              <div class="mb-4">
                <label class="text-subtitle-2 font-weight-bold mb-2 d-block">
                  Review Decision <span class="red--text">*</span>
                </label>
                <v-radio-group
                  v-model="reviewForm.decision"
                  :rules="[rules.required]"
                  :disabled="isReadOnly"
                  row
                  mandatory
                >
                  <v-radio label="Approve" value="approved" color="green">
                    <template v-slot:label>
                      <div class="d-flex align-center">
                        <v-icon color="green" class="mr-2"
                          >mdi-check-circle</v-icon
                        >
                        <span class="font-weight-medium">Approve</span>
                      </div>
                    </template>
                  </v-radio>
                  <v-radio label="Reject" value="rejected" color="red">
                    <template v-slot:label>
                      <div class="d-flex align-center">
                        <v-icon color="red" class="mr-2"
                          >mdi-close-circle</v-icon
                        >
                        <span class="font-weight-medium">Reject</span>
                      </div>
                    </template>
                  </v-radio>
                </v-radio-group>
              </div>

              <v-divider class="mb-4"></v-divider>

              <!-- HR Comments -->
              <div class="mb-4">
                <label class="text-subtitle-2 font-weight-bold mb-2 d-block">
                  HR Comments <span class="red--text">*</span>
                </label>
                <v-textarea
                  v-model="reviewForm.comments"
                  :rules="[rules.required, rules.minLength(10)]"
                  :disabled="isReadOnly"
                  outlined
                  rows="4"
                  placeholder="Provide detailed comments on your decision..."
                  counter="500"
                  maxlength="500"
                  hint="Minimum 10 characters required"
                  persistent-hint
                ></v-textarea>
              </div>

              <!-- Review Date -->
              <div class="mb-4">
                <label class="text-subtitle-2 font-weight-bold mb-2 d-block">
                  Review Date <span class="red--text">*</span>
                </label>
                <v-menu
                  v-model="dateMenu"
                  :close-on-content-click="false"
                  :nudge-right="40"
                  :disabled="isReadOnly"
                  transition="scale-transition"
                  offset-y
                  min-width="290px"
                >
                  <template v-slot:activator="{ on, attrs }">
                    <v-text-field
                      v-model="reviewForm.reviewDate"
                      :rules="[rules.required, rules.notFutureDate]"
                      :disabled="isReadOnly"
                      prepend-icon="mdi-calendar"
                      readonly
                      outlined
                      v-bind="attrs"
                      v-on="on"
                      hint="Date cannot be in the future"
                      persistent-hint
                    ></v-text-field>
                  </template>
                  <v-date-picker
                    v-model="reviewForm.reviewDate"
                    :max="today"
                    @input="dateMenu = false"
                  ></v-date-picker>
                </v-menu>
              </div>

              <v-divider class="mb-4"></v-divider>

              <!-- Participant Validation (if approving) -->
              <v-alert
                v-if="reviewForm.decision === 'd' && participants.length === 0"
                type="warning"
                outlined
                dense
                class="mb-4"
              >
                <div class="text-caption">
                  <v-icon small color="warning">mdi-alert</v-icon>
                  Warning: No participants have been nominated for this
                  training.
                </div>
              </v-alert>

              <!-- Duration Check (if approving) -->
              <v-alert
                v-if="reviewForm.decision === 'approved' && isDurationExceeded"
                type="warning"
                outlined
                dense
                class="mb-4"
              >
                <div class="text-caption">
                  <v-icon small color="warning">mdi-alert</v-icon>
                  Warning: Training duration exceeds 6 months ({{
                    trainingDurationMonths
                  }}
                  months). Please ensure this is appropriate for short-term
                  training.
                </div>
              </v-alert>

              <!-- Action Buttons -->
              <div v-if="!isReadOnly" class="d-flex gap-2">
                <v-btn
                  v-if="valid"
                  :disabled="!valid || submitting"
                  class="success darken-1"
                  dark
                  @click="submitReview()"
                >
                  <v-icon light>mdi-content-save</v-icon>
                  <span>{{
                    existingReview ? "Update Review" : "Submit Review"
                  }}</span>
                </v-btn>
                <v-btn v-else class="green" dark @click="$refs.form.validate()">
                  <v-icon light>mdi-content-save</v-icon>
                  <span>{{
                    existingReview ? "Update Review" : "Submit Review"
                  }}</span>
                </v-btn>
              </div>
            </v-form>
          </v-card-text>
        </v-card>

        <!-- Help Card -->
        <v-card outlined class="elevation-2 mt-4">
          <v-card-title class="blue-grey darken-2 white--text py-3">
            <v-icon left color="white">mdi-information</v-icon>
            Review Guidelines
          </v-card-title>
          <v-card-text class="pa-4">
            <v-list dense>
              <v-list-item>
                <v-list-item-icon>
                  <v-icon color="green">mdi-check</v-icon>
                </v-list-item-icon>
                <v-list-item-content>
                  <v-list-item-subtitle>
                    Verify participant list is appropriate for the training
                  </v-list-item-subtitle>
                </v-list-item-content>
              </v-list-item>

              <v-list-item>
                <v-list-item-icon>
                  <v-icon color="green">mdi-check</v-icon>
                </v-list-item-icon>
                <v-list-item-content>
                  <v-list-item-subtitle>
                    Ensure training duration is within 6 months for short-term
                    training
                  </v-list-item-subtitle>
                </v-list-item-content>
              </v-list-item>

              <v-list-item>
                <v-list-item-icon>
                  <v-icon color="green">mdi-check</v-icon>
                </v-list-item-icon>
                <v-list-item-content>
                  <v-list-item-subtitle>
                    Check that participants are from the correct department
                  </v-list-item-subtitle>
                </v-list-item-content>
              </v-list-item>

              <v-list-item>
                <v-list-item-icon>
                  <v-icon color="green">mdi-check</v-icon>
                </v-list-item-icon>
                <v-list-item-content>
                  <v-list-item-subtitle>
                    Provide clear, detailed comments for your decision
                  </v-list-item-subtitle>
                </v-list-item-content>
              </v-list-item>

              <v-list-item>
                <v-list-item-icon>
                  <v-icon color="orange">mdi-alert</v-icon>
                </v-list-item-icon>
                <v-list-item-content>
                  <v-list-item-subtitle>
                    Rejection should include specific reasons and
                    recommendations
                  </v-list-item-subtitle>
                </v-list-item-content>
              </v-list-item>

              <v-list-item v-if="!isReadOnly && existingReview">
                <v-list-item-icon>
                  <v-icon color="orange">mdi-pencil</v-icon>
                </v-list-item-icon>
                <v-list-item-content>
                  <v-list-item-subtitle>
                    Rejected reviews can be edited within 10 days of submission
                  </v-list-item-subtitle>
                </v-list-item-content>
              </v-list-item>
            </v-list>
          </v-card-text>
        </v-card>
      </v-col>
    </v-row>

    <!-- Confirmation Dialog -->
    <v-dialog v-model="confirmDialog" max-width="500">
      <v-card>
        <v-card-title class="headline">
          <v-icon
            :color="reviewForm.decision === 'approved' ? 'green' : 'red'"
            left
          >
            {{
              reviewForm.decision === "approved"
                ? "mdi-check-circle"
                : "mdi-alert-circle"
            }}
          </v-icon>
          {{
            existingReview
              ? "Confirm Review Update"
              : "Confirm Review Submission"
          }}
        </v-card-title>
        <v-card-text>
          <p class="text-body-1 mb-2">
            Are you sure you want to
            <strong>{{ reviewForm.decision }}</strong> this training
            recommendation response?
          </p>

          <v-alert
            v-if="existingReview"
            type="info"
            outlined
            dense
            class="mt-3 mb-3"
          >
            <div class="text-caption">
              <v-icon small>mdi-information</v-icon>
              This will update your existing review from
              {{ formatDate(existingReview.reviewDate) }}
            </div>
          </v-alert>

          <v-alert
            :type="reviewForm.decision === 'approved' ? 'success' : 'warning'"
            outlined
            dense
            class="mt-3"
          >
            <div class="text-caption">
              <strong>Decision:</strong>
              {{ reviewForm.decision === "approved" ? "APPROVE" : "REJECT" }}
            </div>
            <div class="text-caption mt-1">
              <strong>Participants:</strong> {{ participants.length }}
            </div>
            <div class="text-caption mt-1">
              <strong>Comments:</strong> {{ reviewForm.comments }}
            </div>
          </v-alert>

          <p class="mt-3 text-caption grey--text">
            {{
              existingReview
                ? "This update cannot be undone."
                : "This action cannot be undone."
            }}
            Please ensure all information is correct.
          </p>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn text @click="confirmDialog = false" :disabled="submitting">
            Cancel
          </v-btn>
          <v-btn
            :color="reviewForm.decision === 'approved' ? 'green' : 'red'"
            dark
            @click="confirmSubmit"
            :loading="submitting"
          >
            <v-icon left>mdi-check</v-icon>
            {{ existingReview ? "Update" : "Confirm" }}
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- Success Dialog -->
    <v-dialog v-model="successDialog" max-width="500" persistent>
      <v-card>
        <v-card-title class="green white--text">
          <v-icon color="white" left>mdi-check-circle</v-icon>
          Review {{ existingReview ? "Updated" : "Submitted" }} Successfully
        </v-card-title>
        <v-card-text class="pa-4">
          <div class="text-center py-4">
            <v-icon color="green" size="64">mdi-check-circle-outline</v-icon>
            <p class="text-h6 mt-3">
              Your review has been
              {{ existingReview ? "updated" : "submitted" }} successfully!
            </p>
            <p class="text-body-2 grey--text">
              The training recommendation response has been
              <strong>{{
                reviewForm.decision === "approved" ? "approved" : "rejected"
              }}</strong
              >.
            </p>
          </div>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="primary" @click="goBack">
            Return to List
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </v-container>
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";
import generalMixin from "../../mixins/general";
export default {
  name: "HRTrainingRecommendationReview",
  props: ["queries"],
  mixins: [generalMixin, processQuestionnaire],
  data() {
    return {
      url:
        "http://ihris.org/fhir/Questionnaire/ihris-hr-training-recommendation-review",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/hr-training-recommendation-review-profile",
      valid: false,
      loading: true,
      error: false,

      accessChecked: false,
      isHR: false,
      allowedFacilities: [],
      staffInCoverage: true,
      errorMessage: "",
      submitting: false,
      dateMenu: false,
      confirmDialog: false,
      successDialog: false,

      // Response ID from URL query parameter
      responseId: null,

      // Response data
      responseData: null,
      trainingRecommendation: null,
      participants: [],
      existingReview: null,

      // Review form
      reviewForm: {
        decision: null,
        comments: "",
        reviewDate: new Date().toISOString().substr(0, 10),
      },

      // Validation rules
      rules: {
        required: (value) => !!value || "This field is required",
        minLength: (min) => (value) =>
          (value && value.length >= min) ||
          `Minimum ${min} characters required`,
        notFutureDate: (value) => {
          if (!value) return true;

          const selected = new Date(value);
          selected.setHours(0, 0, 0, 0);

          const today = new Date();
          today.setHours(0, 0, 0, 0);

          return (
            selected.getTime() <= today.getTime() ||
            "Date cannot be in the future"
          );
        },
      },

      // Today's date for date picker
      today: new Date().toISOString().substr(0, 10),
    };
  },

  computed: {
    trainingDurationMonths() {
      if (!this.trainingRecommendation) return 0;
      const start = new Date(this.trainingRecommendation.startDate);
      const end = new Date(this.trainingRecommendation.endDate);
      const months =
        (end.getFullYear() - start.getFullYear()) * 12 +
        (end.getMonth() - start.getMonth());
      return months;
    },

    isDurationExceeded() {
      return this.trainingDurationMonths > 6;
    },

    daysSinceReview() {
      if (!this.existingReview || !this.existingReview.reviewDate) return 0;
      const reviewDate = new Date(this.existingReview.reviewDate);
      const today = new Date();
      const diffTime = Math.abs(today - reviewDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays;
    },

    canEdit() {
      // Can't edit if approved
      if (this.responseData?.status === "approved") return false;

      // Can edit if no existing review
      if (!this.existingReview) return true;

      // Can edit if rejected and less than 10 days old
      if (
        this.responseData?.status === "rejected" &&
        this.daysSinceReview <= 10
      ) {
        return true;
      }

      return false;
    },

    isReadOnly() {
      return !this.canEdit && !!this.existingReview;
    },

    readOnlyReason() {
      if (this.responseData?.status === "approved") {
        return "This response has been approved and the review cannot be modified.";
      }
      if (
        this.responseData?.status === "rejected" &&
        this.daysSinceReview > 10
      ) {
        return `This review was submitted ${this.daysSinceReview} days ago and can no longer be edited (10 day limit).`;
      }
      return "This review cannot be modified.";
    },
  },

  async mounted() {
    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();

    if (!this.isHR) {
      this.loading = false;
      return;
    }

    // Get response ID from URL query parameter
    this.responseId = this.$route.query.response;

    if (!this.responseId) {
      this.error = true;
      this.errorMessage = "No training recommendation response specified";
      this.loading = false;
      return;
    }

    await this.loadResponseData();
  },

  methods: {
    async checkAccess() {
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch("/site/general/getHR/" + practitionerId);
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hrList = await resp.json();

        const matched = Array.isArray(hrList)
          ? hrList.find((h) =>
              h.practitioners.find((p) => p === practitionerId),
            )
          : null;

        if (!matched) {
          this.isHR = false;
          this.accessChecked = true;
          return;
        }

        this.isHR = true;
        const coverageArr = Array.isArray(matched.coverage)
          ? matched.coverage
          : [];
        this.allowedFacilities = coverageArr.map((f) => ({
          id: f.id,
          name: f.name,
        }));
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isHR = false;
      } finally {
        this.accessChecked = true;
      }
    },

    async loadResponseData() {
      try {
        this.loading = true;
        this.error = false;

        // Fetch the training recommendation response
        let response = await fetch("/fhir/Basic/" + this.responseId);

        if (!response.ok) {
          throw new Error("Training recommendation response not found");
        }

        response = await response.json();

        // Parse response data
        this.parseResponseData(response);

        // Fetch training recommendation details
        await this.loadTrainingRecommendation();

        // Fetch participant details
        await this.loadParticipants();

        // Restrict to participants within the HR's facility coverage
        this.staffInCoverage = this.participants.every((p) =>
          this.allowedFacilities.some(
            (f) => String(f.id) === String(p.facility),
          ),
        );

        if (!this.staffInCoverage) {
          this.loading = false;
          return;
        }

        // Check for existing HR review
        await this.loadExistingReview();

        this.loading = false;
      } catch (error) {
        console.error("Error loading response data:", error);
        this.error = true;
        this.errorMessage =
          error.message || "Failed to load training recommendation response";
        this.loading = false;
      }
    },

    parseResponseData(resource) {
      this.responseData = {
        id: resource.id,

        recommendationRef: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/training-recommendation-reference",
          "valueReference",
        )?.reference,

        department:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/department",
            "valueCoding",
          )?.display || "Unknown",

        response: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/training-recommendation-response",
          "valueCoding",
        )?.code,

        responseDisplay:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/training-recommendation-response",
            "valueCoding",
          )?.display || "Unknown",

        status: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/request-status",
          "valueCoding",
        )?.code,

        statusDisplay:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/request-status",
            "valueCoding",
          )?.display || "Unknown",

        submissionDate: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/event-date",
          "valueDate",
        ),

        hodComments: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/comments",
          "valueString",
        ),

        hodUser: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/user-reference",
          "valueReference",
        )?.reference,

        // Get all practitioner references
        practitionerRefs: resource.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
          )
          .map((ext) => ext.valueReference.reference),
      };

      // Validate status - allow underhrreview, approved, or rejected
      if (
        !["underhrreview", "approved", "rejected"].includes(
          this.responseData.status,
        )
      ) {
        throw new Error(
          `This response cannot be viewed. Current status: ${this.responseData.statusDisplay}`,
        );
      }
    },

    async loadTrainingRecommendation() {
      if (!this.responseData.recommendationRef) return;

      const recommendationId = this.responseData.recommendationRef.split(
        "/",
      )[1];
      let response = await fetch("/fhir/Basic/" + recommendationId);

      if (!response.ok) {
        throw new Error("Training recommendation not found");
      }

      const resource = await response.json();

      this.trainingRecommendation = {
        id: resource.id,
        title:
          this.getExtensionValue(
            resource,
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
            "valueString",
          ) || "Untitled Training",

        institution: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/planning-institution",
          "valueString",
        ),

        qualificationLevel: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/qualification-level",
          "valueCoding",
        )?.display,

        qualification: (() => {
          const other = resource.extension?.find(
            (e) => e.url === "http://ihris.org/fhir/StructureDefinition/qualification-name-other",
          )?.valueString;
          const ref = resource.extension?.find(
            (e) => e.url === "http://ihris.org/fhir/StructureDefinition/qualification-name",
          )?.valueReference?.display;
          return other || ref || null;
        })(),

        country: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/country",
          "valueCoding",
        )?.display,

        description: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/description",
          "valueString",
        ),

        departments: [],

        startDate: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/start-date",
          "valueDate",
        ),

        endDate: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/end-date",
          "valueDate",
        ),

        location: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/training-location",
          "valueString",
        ),

        maxParticipants: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/total-participants",
          "valueInteger",
        ),

        methodology: this.getExtensionValue(
          resource,
          "http://ihris.org/fhir/StructureDefinition/learning-methodology",
          "valueCoding",
        )?.display,

        // Extract designation references
        designations: resource.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/designation",
          )
          .map(
            (ext) =>
              ext.valueReference?.display || ext.valueReference?.reference,
          )
          .filter(Boolean),

        // Extract salary grade references
        salaryGrades: resource.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/salary-grade",
          )
          .map(
            (ext) =>
              ext.valueReference?.display || ext.valueReference?.reference,
          )
          .filter(Boolean),

        // Extract age criteria
        ageCriteria: resource.extension
          .filter(
            (ext) =>
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/training-recommendation-age",
          )
          .map((ext) => {
            const ageExt = ext.extension || [];
            const typeExt = ageExt.find((e) => e.url === "condition");
            const valueExt = ageExt.find((e) => e.url === "exact");
            const minValueExt = ageExt.find((e) => e.url === "min");
            const maxValueExt = ageExt.find((e) => e.url === "max");

            if (typeExt) {
              const ageItem = {
                type: typeExt.valueString,
              };

              if (valueExt) {
                ageItem.value = valueExt.valueInteger;
              }
              if (minValueExt) {
                ageItem.minValue = minValueExt.valueInteger;
              }
              if (maxValueExt) {
                ageItem.maxValue = maxValueExt.valueInteger;
              }

              return ageItem;
            }
            return null;
          })
          .filter(Boolean),
      };
      if (this.trainingRecommendation.designations.length) {
        for (let index in this.trainingRecommendation.designations) {
          let designation = this.trainingRecommendation.designations[index];
          let desDet = await fetch("/fhir/" + designation);
          desDet = await desDet.json();
          let name = desDet.extension.find((ext) => {
            return (
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
            );
          })?.valueString;
          this.trainingRecommendation.designations[index] = name;
        }
      }
      if (this.trainingRecommendation.salaryGrades.length) {
        for (let index in this.trainingRecommendation.salaryGrades) {
          let grade = this.trainingRecommendation.salaryGrades[index];
          let gradeDet = await fetch("/fhir/" + grade);
          gradeDet = await gradeDet.json();
          let name = gradeDet.extension.find((ext) => {
            return (
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
            );
          })?.valueString;
          this.trainingRecommendation.salaryGrades[index] = name;
        }
      }

      let departments = resource.extension.filter((ext) => {
        return (
          ext.url ===
          "http://ihris.org/fhir/StructureDefinition/training-recommendation-department"
        );
      });
      for (let department of departments) {
        this.trainingRecommendation.departments.push({
          name: department.extension.find((ext) => {
            return ext.url === "department";
          })?.valueCoding?.display,
          participants: department.extension.find((ext) => {
            return ext.url === "total-participants";
          })?.valueInteger,
        });
      }
    },

    async loadParticipants() {
      if (
        !this.responseData.practitionerRefs ||
        this.responseData.practitionerRefs.length === 0
      ) {
        this.participants = [];
        return;
      }

      this.participants = [];

      for (const practitionerId of this.responseData.practitionerRefs) {
        try {
          let response = await fetch(
            "/fhir/PractitionerRole?practitioner=" +
              practitionerId +
              "&_include=PractitionerRole:practitioner&_include=PractitionerRole:roleposition",
          );

          if (!response.ok) {
            console.error(`Failed to load practitioner ${practitionerId}`);
            continue;
          }

          response = await response.json();

          let practitioner = response.entry?.find((entry) => {
            return entry.resource.resourceType === "Practitioner";
          })?.resource;

          if (!practitioner) {
            console.error(`Practitioner not found for ${practitionerId}`);
            continue;
          }

          let position = response.entry?.find((entry) => {
            return entry.resource.resourceType === "Basic";
          })?.resource;

          // Get practitioner details
          const name = practitioner.name?.[0];
          let fullName = "";

          if (name) {
            if (name.given && name.given.length) {
              fullName = name.given.join(" ");
            }

            if (name.family) {
              fullName += " " + name.family;
            }
          }
          let age = null;
          if (practitioner.birthDate) {
            const birthDate = new Date(practitioner.birthDate);
            const today = new Date();
            age = today.getFullYear() - birthDate.getFullYear();
            const monthDiff = today.getMonth() - birthDate.getMonth();
            if (
              monthDiff < 0 ||
              (monthDiff === 0 && today.getDate() < birthDate.getDate())
            ) {
              age--;
            }
          }

          const jobTitle = position?.extension?.find((ext) => {
            return (
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
            );
          })?.valueString;
          let grade = position?.extension?.find((ext) => {
            return (
              ext.url ===
              "http://ihris.org/fhir/StructureDefinition/salary-grade"
            );
          })?.valueReference?.reference;
          if (grade) {
            grade = await fetch("/fhir/" + grade);
            grade = await grade.json();
          }
          const facility = position?.extension
            ?.find((ext) => {
              return (
                ext.url === "http://ihris.org/fhir/StructureDefinition/facility"
              );
            })
            ?.valueReference?.reference?.split("/")[1];
          this.participants.push({
            id: practitionerId,
            name: fullName.trim() || "Unknown",
            jobTitle: jobTitle || "Not specified",
            age,
            grade: grade?.extension?.find((ext) => {
              return (
                ext.url ===
                "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
              );
            })?.valueString,
            facility,
          });
        } catch (error) {
          console.error(`Error loading participant ${practitionerId}:`, error);
        }
      }
    },

    async loadExistingReview() {
      try {
        // Search for existing HR review for this response
        let response = await fetch(
          `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/hr-training-recommendation-review-profile&trainingrecommendationresponse=Basic/${this.responseId}`,
        );

        if (!response.ok) {
          // No existing review found, which is fine
          return;
        }

        const searchResults = await response.json();

        if (searchResults.entry && searchResults.entry.length > 0) {
          const reviewResource = searchResults.entry[0].resource;
          this.fhirId = reviewResource.id;
          // Parse existing review
          this.existingReview = {
            id: reviewResource.id,
            decision: this.getExtensionValue(
              reviewResource,
              "http://ihris.org/fhir/StructureDefinition/review-status",
              "valueCoding",
            )?.code,
            comments: this.getExtensionValue(
              reviewResource,
              "http://ihris.org/fhir/StructureDefinition/comments",
              "valueString",
            ),
            reviewDate: this.getExtensionValue(
              reviewResource,
              "http://ihris.org/fhir/StructureDefinition/event-date",
              "valueDate",
            ),
            reviewerRef: this.getExtensionValue(
              reviewResource,
              "http://ihris.org/fhir/StructureDefinition/user-reference",
              "valueReference",
            )?.reference,
            reviewerName: "HR Officer", // You can fetch the actual name if needed
          };

          this.reviewForm.decision = this.existingReview.decision;
          this.reviewForm.comments = this.existingReview.comments;
          this.reviewForm.reviewDate = this.existingReview.reviewDate;
        }
      } catch (error) {
        console.error("Error loading existing review:", error);
        // Don't throw - it's okay if there's no existing review
      }
    },

    getExtensionValue(resource, url, type) {
      const extension = resource.extension?.find((ext) => ext.url === url);
      return extension ? extension[type] : null;
    },

    formatDate(dateString) {
      if (!dateString) return "Not specified";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric",
      });
    },
    formatAgeCriteria(ageItem) {
      if (!ageItem || !ageItem.type) return "";

      switch (ageItem.type) {
        case "greater-than":
          return `Age > ${ageItem.minValue}`;
        case "less-than":
          return `Age < ${ageItem.maxValue}`;
        case "range":
          return `Age ${ageItem.minValue}-${ageItem.maxValue}`;
        case "exact":
          return `Age = ${ageItem.value}`;
        default:
          return "";
      }
    },

    calculateDuration(startDate, endDate) {
      if (!startDate || !endDate) return "Not specified";

      const start = new Date(startDate);
      const end = new Date(endDate);
      const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));

      if (days < 30) {
        return `${days} day${days !== 1 ? "s" : ""}`;
      } else {
        const months = Math.round(days / 30);
        return `${months} month${months !== 1 ? "s" : ""} (${days} days)`;
      }
    },

    getResponseColor(response) {
      switch (response) {
        case "interested":
          return "green";
        case "not-interested":
          return "red";
        default:
          return "grey";
      }
    },

    getResponseIcon(response) {
      switch (response) {
        case "interested":
          return "mdi-hand-okay";
        case "not-interested":
          return "mdi-hand-back-left";
        default:
          return "mdi-help-circle";
      }
    },

    submitReview() {
      // Validate form
      this.$refs.form.validate();
      if (!this.valid) return;

      // Show confirmation dialog
      this.confirmDialog = true;
    },

    async confirmSubmit() {
      try {
        this.submitting = true;

        // Set query parameters for workflow
        this.$route.query.comments = this.reviewForm.comments;
        this.$route.query.date = this.reviewForm.reviewDate;
        this.$route.query.decision = this.reviewForm.decision;

        // Process FHIR submission
        await this.processFHIR();

        this.confirmDialog = false;
        this.successDialog = true;
        await this.loadResponseData();
      } catch (error) {
        console.error("Error submitting review:", error);
        this.error = true;
        this.errorMessage =
          error.message || "Failed to submit review. Please try again.";
        this.confirmDialog = false;
      } finally {
        this.submitting = false;
      }
    },

    goBack() {
      this.$router.go(-1);
    },
  },
};
</script>

